interface DashboardControlBarProps {
  workspaceId: string;
  dashboardId: string;
  directories: { id: string; name: string }[];
  isEditing: boolean;
  isSaving: boolean;
  hasChanges: boolean;
  isReadOnly: boolean;
  isAIAvailable?: boolean;
  aiUnavailableReason?: TAIUnavailableReason;
  onRefresh: () => void;
  /**
   * Single-key shortcut that toggles edit mode. Its key cap sits on whichever button it currently
   * triggers: the pencil in view mode, save while there are changes, cancel while there are none.
   */
  editHotkey?: string;
  onEditToggle: () => void;
  onSave: () => void;
  onCancel: () => void;
}

export const DashboardControlBar = ({
  workspaceId,
  dashboardId,
  directories,
  isEditing,
  isSaving,
  hasChanges,
  isReadOnly,
  isAIAvailable,
  aiUnavailableReason,
  onRefresh,
  editHotkey,
  onEditToggle,
  onSave,
  onCancel,
}: Readonly<DashboardControlBarProps>) => {
  const router = useRouter();
  const { t } = useTranslation();
  const [isDeleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [isAddExistingDialogOpen, setIsAddExistingDialogOpen] = useState(false);
  const queryClient = useQueryClient();
  const deleteMutation = useMutation({
    mutationFn: () => deleteDashboard(dashboardId),
    onSuccess: () => {
      queryClient.removeQueries({ queryKey: dashboardKeys.detail(dashboardId) });
      return queryClient.invalidateQueries({ queryKey: dashboardKeys.lists() });
    },
  });

  const handleDeleteDashboard = () =>
    deleteMutation.mutate(undefined, {
      onSuccess: () => {
        router.push(`/workspaces/${workspaceId}/dashboards`);
        toast.success(t("workspace.analysis.dashboards.delete_success"));
      },
      onError: (error) =>
        toast.error(getChartApiErrorMessage(error, t("workspace.analysis.dashboards.delete_failed"))),
      onSettled: () => setDeleteDialogOpen(false),
    });

  const editModeActions = [
    {
      icon: isSaving ? null : CheckIcon,
      tooltip: hasChanges ? t("common.save") : t("common.no_changes"),
      shortcut: hasChanges && !isSaving ? editHotkey : undefined,
      onClick: onSave,
      isVisible: true,
      isLoading: isSaving,
      disabled: isSaving || !hasChanges,
    },
    {
      icon: XIcon,
      tooltip: t("common.cancel"),
      shortcut: !hasChanges && !isSaving ? editHotkey : undefined,
      onClick: onCancel,
      isVisible: true,
      disabled: isSaving,
    },
  ];

  const viewModeActions = [
    {
      icon: RefreshCwIcon,
      tooltip: t("common.refresh"),
      onClick: onRefresh,
      isVisible: true,
    },
    {
      icon: PencilIcon,
      tooltip: t("common.edit"),
      shortcut: editHotkey,
      onClick: onEditToggle,
      isVisible: !isReadOnly,
    },
    {
      icon: TrashIcon,
      tooltip: t("common.delete"),
      onClick: () => setDeleteDialogOpen(true),
      isVisible: !isReadOnly,
    },
  ];

  return (
    <>
      {isEditing ? (
        <IconBar actions={editModeActions} />
      ) : (
        <div className="flex items-center gap-2">
          {!isReadOnly && (
            <Button onClick={() => setIsAddExistingDialogOpen(true)}>
              <PlusIcon />
              {t("common.add_charts")}
            </Button>
          )}
          <IconBar actions={viewModeActions} />
        </div>
      )}
      <DeleteDialog
        deleteWhat={t("workspace.analysis.dashboards.dashboard")}
        open={isDeleteDialogOpen}
        setOpen={setDeleteDialogOpen}
        onDelete={handleDeleteDashboard}
        text={t("workspace.analysis.dashboards.dashboard_delete_confirmation")}
        isDeleting={deleteMutation.isPending}
      />
      <AddExistingChartsDialog
        open={isAddExistingDialogOpen}
        onOpenChange={setIsAddExistingDialogOpen}
        workspaceId={workspaceId}
        dashboardId={dashboardId}
        directories={directories}
        onSuccess={() => {
          setIsAddExistingDialogOpen(false);
          onRefresh();
        }}
        isAIAvailable={isAIAvailable}
        aiUnavailableReason={aiUnavailableReason}
      />
    </>
  );
};

import type { TChartConfig, TChartQuery } from "@formbricks/types/analysis";
import type { TV3ChartData, TV3ChartResource } from "@/app/api/v3/charts/lib/resources";
import type {
  TV3DashboardListItem,
  TV3DashboardResource,
  TV3DashboardWidget,
} from "@/app/api/v3/dashboards/lib/resources";
import { V3ApiError, parseV3ApiError } from "@/modules/api/lib/v3-client";
import type {
  AnalyticsResponse,
  TChartDataRow,
  TChartType,
  TChartWithCreator,
  TDashboardWidget,
} from "@/modules/ee/analysis/types/analysis";

/**
 * The app's client for the public chart and dashboard API (ADR 0002: the app goes through the same
 * `/api/v3` contract agents use). Every function throws the parsed problem (`V3ApiError`) on a non-2xx,
 * so callers branch on `code` rather than on prose.
 */

const CHARTS_PATH = "/api/v3/charts";
const DASHBOARDS_PATH = "/api/v3/dashboards";
const JSON_HEADERS = { "Content-Type": "application/json" };

/** Bounds a write so a stalled request cannot leave a dialog's spinner running forever. */
export const MUTATION_TIMEOUT_MS = 15_000;

/** A problem's `details` are typed `unknown`; the operations that set them put a JSON object there. */
const isPlainRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

export type TV3ListPage<T> = { data: T[]; meta: { limit: number; nextCursor: string | null } };

/**
 * A chart as the app's components use it. The public resource names its Feedback Dataset `datasetId`;
 * the builder and the rest of the analysis module still call it `feedbackDirectoryId`, so the translation
 * happens once, here at the boundary, instead of in every component.
 */
export type TAppChart = TChartWithCreator & { dashboards: TV3ChartResource["dashboards"] };

export const toAppChart = (resource: TV3ChartResource): TAppChart => ({
  id: resource.id,
  name: resource.name,
  type: resource.type,
  query: resource.query as TAppChart["query"],
  config: resource.config as TAppChart["config"],
  feedbackDirectoryId: resource.datasetId,
  createdAt: new Date(resource.createdAt),
  updatedAt: new Date(resource.updatedAt),
  creator: resource.creator,
  dashboards: resource.dashboards,
});

const readData = async <T>(response: Response): Promise<T> => {
  if (!response.ok) throw await parseV3ApiError(response);
  return ((await response.json()) as { data: T }).data;
};

export type TChartListFilters = { nameContains?: string; datasetId?: string };

export const buildChartListSearchParams = ({
  workspaceId,
  limit,
  cursor,
  filters,
}: {
  workspaceId: string;
  limit: number;
  cursor?: string | null;
  filters?: TChartListFilters;
}): URLSearchParams => {
  const searchParams = new URLSearchParams({ workspaceId, limit: String(limit) });
  if (cursor) searchParams.set("cursor", cursor);

  const nameContains = filters?.nameContains?.trim();
  if (nameContains) searchParams.set("filter[name][contains]", nameContains);
  if (filters?.datasetId) searchParams.set("filter[datasetId][eq]", filters.datasetId);

import { v7 as uuidv7 } from "uuid";
import { prisma } from "@formbricks/database";
import { Prisma, Webhook } from "@formbricks/database/prisma";
import { PrismaErrorType } from "@formbricks/database/types/error";
import { ZId } from "@formbricks/types/common";
import {
  DatabaseError,
  InvalidInputError,
  ResourceNotFoundError,
  UnknownError,
} from "@formbricks/types/errors";
import { generateWebhookSecret } from "@/lib/crypto";
import { validateInputs } from "@/lib/utils/validate";
import { validateWebhookUrl } from "@/lib/utils/validate-webhook-url";
import { getTranslate } from "@/lingodotdev/server";
import {
  WebhookDeliveryTimeoutError,
  sendSignedWebhookRequest,
} from "@/modules/integrations/webhooks/lib/send-signed-webhook";
import { isDiscordWebhook } from "@/modules/integrations/webhooks/lib/utils";
import { TWebhookInput } from "../types/webhooks";

const getWebhookTestErrorMessage = async (statusCode: number): Promise<string | null> => {
  switch (statusCode) {
    case 500: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_internal_server_error");
    }
    case 404: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_not_found_error");
    }
    case 405: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_method_not_allowed_error");
    }
    case 502: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_bad_gateway_error");
    }
    case 503: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_service_unavailable_error");
    }
    case 504: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_gateway_timeout_error");
    }
    default:
      return null;
  }
};

export const updateWebhook = async (
  webhookId: string,
  webhookInput: Partial<TWebhookInput>
): Promise<boolean> => {
  if (webhookInput.url) {
    await validateWebhookUrl(webhookInput.url);
  }

  try {
    await prisma.webhook.update({
      where: {
        id: webhookId,
      },
      data: {
        name: webhookInput.name,
        url: webhookInput.url,
        triggers: webhookInput.triggers,
        surveyIds: webhookInput.surveyIds || [],
      },
    });

    return true;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const deleteWebhook = async (id: string): Promise<boolean> => {
  try {
    await prisma.webhook.delete({
      where: {
        id,
      },
    });

    return true;
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === PrismaErrorType.RecordNotFound
    ) {
      throw new ResourceNotFoundError("Webhook", id);
    }
    throw new DatabaseError(`Database error when deleting webhook with ID ${id}`);
  }
};

export const createWebhook = async (
  workspaceId: string,
  webhookInput: TWebhookInput,
  secret?: string
): Promise<Webhook> => {
  await validateWebhookUrl(webhookInput.url);

  try {
    if (isDiscordWebhook(webhookInput.url)) {
      throw new UnknownError("Discord webhooks are currently not supported.");
    }

    const signingSecret = secret ?? generateWebhookSecret();

    const webhook = await prisma.webhook.create({
      data: {
        ...webhookInput,
        surveyIds: webhookInput.surveyIds || [],
        secret: signingSecret,
        workspace: {
          connect: {
            id: workspaceId,
          },
        },
      },
    });

    return webhook;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    if (!(error instanceof InvalidInputError)) {
      throw new DatabaseError(`Database error when creating webhook for workspace ${workspaceId}`);
    }

    throw error;
  }
};

export const getWebhooks = async (workspaceId: string): Promise<Webhook[]> => {
  validateInputs([workspaceId, ZId]);

  try {
    const webhooks = await prisma.webhook.findMany({
      where: {
        workspaceId,
      },
      orderBy: {
        createdAt: "desc",
      },
    });
    return webhooks;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const testEndpoint = async (url: string, secret?: string): Promise<boolean> => {
  if (isDiscordWebhook(url)) {
    throw new UnknownError("Discord webhooks are currently not supported.");
  }

  try {
    // Same transport as real deliveries (SSRF validation, DNS pinning, signing, redirect policy,
    // timeout), so what the button proves is what the background worker will do.
    const { statusCode } = await sendSignedWebhookRequest({
      url,
      secret,
      body: JSON.stringify({ event: "testEndpoint" }),
      messageId: uuidv7(),
    });

    // With `redirect: "manual"` undici returns the actual 30x. Surface it as a clear error instead of
    // a misleading success; with `redirect: "follow"` (internal URLs allowed) this branch is unreachable.
    if (statusCode >= 300 && statusCode < 400) {
      throw new InvalidInputError("Webhook endpoint returned a redirect, which is not allowed");
    }

    const errorMessage = await getWebhookTestErrorMessage(statusCode);

    if (errorMessage) {
      throw new InvalidInputError(errorMessage);
    }

    return true;
  } catch (error) {
    if (error instanceof WebhookDeliveryTimeoutError) {
      throw new UnknownError(`Request timed out after ${Math.round(error.timeoutMs / 1000)} seconds`);
    }

    if (error instanceof InvalidInputError || error instanceof UnknownError) {
      throw error;
    }

    throw new UnknownError(
      `Error while fetching the URL: ${error instanceof Error ? error.message : "Unknown error occurred"}`
    );
  }
};

"use server";

import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import { assertCan } from "@/lib/authorization";
import { generateWebhookSecret } from "@/lib/crypto";
import { capturePostHogEvent } from "@/lib/posthog";
import { assertNewlyAttachedSurveysWorkspaceVisible } from "@/lib/survey/visibility/outbound";
import { authenticatedActionClient } from "@/lib/utils/action-client";
import {
  getOrganizationIdFromWebhookId,
  getOrganizationIdFromWorkspaceId,
  getWorkspaceIdFromWebhookId,
} from "@/lib/utils/helper";
import {
  getWebhook,
  getWebhookWithSecret,
} from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";
import {
  createWebhook,
  deleteWebhook,
  testEndpoint,
  updateWebhook,
} from "@/modules/integrations/webhooks/lib/webhook";
import { ZWebhookInput } from "@/modules/integrations/webhooks/types/webhooks";

const ZCreateWebhookAction = z.object({
  workspaceId: ZId,
  webhookInput: ZWebhookInput,
  webhookSecret: z.string().optional(),
});

export const createWebhookAction = authenticatedActionClient.inputSchema(ZCreateWebhookAction).action(
  withAuditLogging("created", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWorkspaceId(parsedInput.workspaceId);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: parsedInput.workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, parsedInput.workspaceId);
    await assertNewlyAttachedSurveysWorkspaceVisible(parsedInput.webhookInput.surveyIds ?? []);
    const webhook = await createWebhook(
      parsedInput.workspaceId,
      parsedInput.webhookInput,
      parsedInput.webhookSecret
    );
    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.newObject = parsedInput.webhookInput;

    capturePostHogEvent(
      ctx.user.id,
      "integration_connected",
      {
        integration_type: "webhook",
        organization_id: organizationId,
        workspace_id: parsedInput.workspaceId,
      },
      { organizationId, workspaceId: parsedInput.workspaceId }
    );

    return webhook;
  })
);

const ZDeleteWebhookAction = z.object({
  id: ZId,
});

export const deleteWebhookAction = authenticatedActionClient.inputSchema(ZDeleteWebhookAction).action(
  withAuditLogging("deleted", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWebhookId(parsedInput.id);
    const workspaceId = await getWorkspaceIdFromWebhookId(parsedInput.id);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.webhookId = parsedInput.id;
    ctx.auditLoggingCtx.oldObject = { ...(await getWebhook(parsedInput.id)) };

    const result = await deleteWebhook(parsedInput.id);
    return result;
  })
);

const ZUpdateWebhookAction = z.object({
  webhookId: ZId,
  webhookInput: ZWebhookInput,
});

export const updateWebhookAction = authenticatedActionClient.inputSchema(ZUpdateWebhookAction).action(
  withAuditLogging("updated", "webhook", async ({ ctx, parsedInput }) => {
