const sendDelete = async (path: string): Promise<void> => {
  const response = await fetch(path, {
    method: "DELETE",
    cache: "no-store",
    signal: AbortSignal.timeout(MUTATION_TIMEOUT_MS),
  });
  if (!response.ok) throw await parseV3ApiError(response);
};

