  layout: TDashboardWidget["layout"],
  place: (layout?: TDashboardWidget["layout"]) => Promise<T>
): Promise<T> => {
  try {
    return await place(layout);
  } catch (error) {
    if (error instanceof V3ApiError && error.status === 422) return place();
    throw error;
  }
};

