/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — clone a webhook into a new one with a fresh secret.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { duplicateV3Webhook } from "../../lib/operations";
import { ZV3WebhookIdParams } from "../../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "webhook",
  schemas: { params: ZV3WebhookIdParams, query: ZV3EmptyQuery },
  handler: async ({ parsedInput, authentication, auditLog, requestId, instance }) =>
    duplicateV3Webhook({
      webhookId: parsedInput.params.webhookId,
      authentication,
      auditLog,
      requestId,
      instance,
    }),
});

import { Webhook } from "@formbricks/database/prisma";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import { assertCan } from "@/lib/authorization";
import { generateWebhookSecret } from "@/lib/crypto";
import { capturePostHogEvent } from "@/lib/posthog";
import {
  getOrganizationIdFromWebhookId,
  getWorkspaceIdFromWebhookId,
} from "@/lib/utils/helper";
import {
  getWebhookWithSecret,
} from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { TV3Authentication, TV3AuditLog } from "@/app/api/v3/lib/types";
import { createWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { TWebhookInput } from "@/modules/integrations/webhooks/types/webhooks";
import type { TV3WebhookIdParams } from "./schemas";

export const duplicateV3Webhook = async ({
  webhookId,
  authentication,
  auditLog,
  requestId,
  instance,
}: {
  webhookId: string;
  authentication: TV3Authentication;
  auditLog?: TV3AuditLog;
  requestId: string;
  instance: string;
}): Promise<{ data: Webhook }> => {
  const organizationId = await getOrganizationIdFromWebhookId(webhookId);
  const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);

  await assertCan(
    { type: "user", id: authentication.userId! },
    "workspace.write",
    { type: "workspace", id: workspaceId }
  );

  await applyRateLimit(rateLimitConfigs.api.v3, workspaceId);

  const webhookResult = await getWebhookWithSecret(webhookId);
  if (!webhookResult.ok) {
    throw new ResourceNotFoundError("Webhook", webhookId);
  }

  const original = webhookResult.data;
  const newSecret = generateWebhookSecret();

  const webhookInput: TWebhookInput = {
    name: original.name ? `Copy of ${original.name}` : null,
    url: original.url,
    source: "user" as const,
    triggers: original.triggers,
    surveyIds: original.surveyIds,
  };

  const webhook = await createWebhook(workspaceId, webhookInput, newSecret);

  // Audit logging — mirror the server action's behavior
  if (auditLog) {
    auditLog.organizationId = organizationId;
    auditLog.newObject = webhook;
  }

  capturePostHogEvent(
    authentication.userId!,
    "integration_connected",
    {
      integration_type: "webhook",
      organization_id: organizationId,
      workspace_id: workspaceId,
    },
    { organizationId, workspaceId }
  );

  return { data: webhook };
};

import { z } from "zod";
import { ZId } from "@formbricks/types/common";

export const ZV3WebhookIdParams = z.object({
  webhookId: ZId,
});

export type TV3WebhookIdParams = z.infer<typeof ZV3WebhookIdParams>;

import type { Webhook } from "@formbricks/database/prisma-browser";
import { V3ApiError, parseV3ApiError } from "@/modules/api/lib/v3-client";

const WEBHOOKS_PATH = "/api/v3/webhooks";

/**
 * The app's client for the webhook API. Every function throws the parsed problem (`V3ApiError`)
 * on a non-2xx, so callers branch on `code` rather than on prose.
 */

/**
 * A webhook as the app's components use it. Mirrors the TV3WebhookResource shape.
 */
export type TAppWebhook = Webhook;

/**
 * Duplicates a webhook. Returns the newly created webhook on success.
 */
export const duplicateWebhook = async (
  webhookId: string
): Promise<TAppWebhook> => {
  const response = await fetch(`${WEBHOOKS_PATH}/${encodeURIComponent(webhookId)}/duplicate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    cache: "no-store",
    signal: AbortSignal.timeout(15_000),
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  const json = (await response.json()) as { data: Webhook };
  return json.data;
};

/**
 * Returns a human-readable error message from a V3ApiError, falling back to a default.
 */
export const getWebhookApiErrorMessage = (error: unknown, fallback: string): string => {
  if (error instanceof V3ApiError) {
    if (error.code === "not_found") {
      return "Webhook not found";
    }
    if (error.code === "unauthorized") {
      return "You don't have permission to duplicate this webhook";
    }
    if (error.invalid_params?.length) {
      return error.invalid_params[0].reason ?? fallback;
    }
    return error.detail ?? fallback;
  }
  return fallback;
};

/** TanStack Query keys for the Webhooks area's client-fetched lists. */
export const webhookKeys = {
  all: ["webhooks"] as const,
  lists: () => [...webhookKeys.all, "list"] as const,
};

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { CopyIcon } from "lucide-react";
import { TFunction } from "i18next";
import { useRouter } from "next/navigation";
import { useTranslation } from "react-i18next";
import { toast } from "react-hot-toast";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { timeSince } from "@/lib/time";
import { duplicateWebhook, getWebhookApiErrorMessage } from "@/modules/integrations/webhooks/lib/api-client";
import { webhookKeys } from "@/modules/integrations/webhooks/lib/query-keys";
import { RestrictedSurveyHint } from "@/modules/survey/visibility/components/restricted-survey-hint";
import { hasRestrictedAttachedSurvey } from "@/modules/survey/visibility/lib/outbound";
import { Badge } from "@/modules/ui/components/badge";
import { Button } from "@/modules/ui/components/button";

const renderSelectedSurveysText = (webhook: Webhook, allSurveys: TSurvey[]) => {
  let surveyNames: string[];
  if (webhook.surveyIds.length === 0) {
    surveyNames = allSurveys.map((survey) => survey.name);
  } else {
    surveyNames = webhook.surveyIds.map((surveyId) => {
      const survey = allSurveys.find((survey) => survey.id === surveyId);
      return survey ? survey.name : "";
    });
  }
  return surveyNames.join(", ");
};

const renderSelectedTriggersText = (webhook: Webhook, t: TFunction): string => {
  return webhook.triggers
    .map((trigger) => {
      switch (trigger) {
        case "responseCreated":
          return t("workspace.integrations.webhooks.response_created");
        case "responseUpdated":
          return t("workspace.integrations.webhooks.response_updated");
        case "responseFinished":
          return t("workspace.integrations.webhooks.response_finished");
        default:
          return trigger;
      }
    })
    .join(", ");
};

export const WebhookRowData = ({
  webhook,
  surveys,
  surveyVisibilityEnabled,
}: Readonly<{ webhook: Webhook; surveys: TSurvey[]; surveyVisibilityEnabled: boolean }>) => {
  const { t, i18n } = useTranslation();
  const locale = i18n.resolvedLanguage ?? i18n.language ?? "en-US";
  const router = useRouter();
  const queryClient = useQueryClient();

  const duplicateMutation = useMutation({
    mutationFn: () => duplicateWebhook(webhook.id),
    onSuccess: () => {
      toast.success(t("workspace.integrations.webhooks.webhook_duplicate_successfully"));
      void queryClient.invalidateQueries({ queryKey: webhookKeys.lists() });
      void router.refresh();
    },
    onError: (error) => {
      const errorMessage = getWebhookApiErrorMessage(
        error,
        t("workspace.integrations.webhooks.webhook_duplicate_failed")
      );
      toast.error(errorMessage);
    },
  });

  return (
    <div className="mt-2 grid h-auto grid-cols-13 content-center rounded-lg py-2 hover:bg-slate-100">
      <div className="col-span-3 flex items-center truncate pl-6 text-sm">
        <div className="flex items-center">
          <div className="text-left">
            <div className="font-medium text-slate-900">{webhook.name ? webhook.name : "-"}</div>
            {hasRestrictedAttachedSurvey(webhook, surveys, surveyVisibilityEnabled) && (
              <RestrictedSurveyHint />
            )}
          </div>
        </div>
      </div>
      <div className="col-span-1 my-auto text-center text-sm">
        <Badge
          className="text-xs"
          variant={
            webhook.source === "user"
              ? "success"
              : webhook.source === "zapier"
                ? "warning"
                : webhook.source === "make"
                  ? "info"
                  : webhook.source === "n8n"
                    ? "info"
                    : webhook.source === "activepieces"
                      ? "info"
                      : "neutral"
          }>
          {webhook.source === "user" ? "User" : webhook.source}
        </Badge>
      </div>
      <div className="col-span-4 my-auto text-center text-sm text-slate-800">
        {renderSelectedSurveysText(webhook, surveys)}
      </div>
      <div className="col-span-2 my-auto text-center text-sm text-slate-800">
        {renderSelectedTriggersText(webhook, t)}
      </div>
      <div className="col-span-1 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        {timeSince(webhook.createdAt.toString(), locale)}
      </div>
      <div className="col-span-2 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        {timeSince(webhook.updatedAt.toString(), locale)}
      </div>
      <div className="col-span-1 my-auto text-center">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="text-slate-500 hover:text-slate-700"
          onClick={() => duplicateMutation.mutate()}
          disabled={duplicateMutation.isPending}
          loading={duplicateMutation.isPending}
        >
          <CopyIcon className="size-4" />
          <span className="sr-only">{t("workspace.integrations.webhooks.webhook_duplicate")}</span>
        </Button>
      </div>
    </div>
  );
};
